"""Build a self-contained, illustrated technical report from the reference evidence."""
import base64,datetime,hashlib,html,json,os,shutil,sys
from pathlib import Path
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[1]
RUN=Path(sys.argv[1]).resolve() if len(sys.argv)>1 else ROOT/'evidence'/json.loads((ROOT/'evidence/reference.json').read_text())['run']
OUT=ROOT/'docs/reports';OUT.mkdir(parents=True,exist_ok=True)
ASSETS=ROOT/'docs/assets/report'
results=json.loads((RUN/'results.json').read_text());summary=json.loads((RUN/'evidence-summary.json').read_text());alerts=json.loads((RUN/'alerts.json').read_text());triage=json.loads((RUN/'triage.json').read_text());runtime=json.loads((RUN/'runtime-checks.json').read_text());audit=json.loads((RUN/'sandbox-audit.json').read_text());versions=json.loads((RUN/'tool-versions.json').read_text())
def esc(value):return html.escape(str(value))
def data_uri(path):
 p=Path(path);mime='image/svg+xml' if p.suffix=='.svg' else 'image/png'
 return 'data:'+mime+';base64,'+base64.b64encode(p.read_bytes()).decode()
def figure(path,caption,cls=''):
 return f'<figure class="{cls}"><img src="{data_uri(path)}" alt="{esc(caption)}"><figcaption>{esc(caption)}</figcaption></figure>'
def diagram(name,caption,cls='diagram'):return figure(ASSETS/(name+'.svg'),caption,cls)
def table(head,rows,cls=''):
 return '<table class="'+cls+'"><thead><tr>'+''.join('<th>'+esc(x)+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'
def callout(title,text):return '<aside><b>'+esc(title)+'</b><p>'+text+'</p></aside>'
def pre(value):return '<pre>'+esc(value)+'</pre>'
def paragraph(value):return '<p>'+value+'</p>'
pages=[];sections=[]
def page(label,title,body):
 number=len(pages)+1;sections.append((number,label,title.replace('<br>',' ')))
 pages.append(f'<section class="page" id="page-{number}"><header><span>CYBERTHREAT / THREAT ANALYSIS</span><span>{esc(label)}</span></header><h1>{title}</h1>{body}<footer><span>RAPPORT TECHNIQUE / {esc(RUN.name)}</span><span>{number:02}</span></footer></section>')
cover=f'''<section class="page cover" id="page-1"><header><span>CYBERTHREAT</span><span>SSIR-5-F</span></header><div class="cover-category">RAPPORT TECHNIQUE</div><h1>Analyse des menaces<br>en environnement isolé</h1><h2>CyberThreat / Threat Analysis</h2><p class="cover-sub">Reconnaissance réseau, collecte de preuves et validation des protections.<br>Intégration locale OpenCode et MCP.</p>{diagram('pipeline','Vue d’ensemble du workflow implémenté.','cover-diagram')}<div class="cover-bottom"><div><span class="label">AUTEURS</span><p>WAEL RDIFI<br>RIM MENZLI</p></div><div><span class="label">CLASSE / ÉDITION</span><p>SSIR-5-F<br>12 octobre 2026</p></div></div><footer><span>Scénarios contrôlés / artefacts vérifiables</span><span>01</span></footer></section>'''
pages.append(cover)
# Contents is populated after all chapters have been created.
pages.append('CONTENTS_PLACEHOLDER')
phases=summary['phases'];packet_total=sum(x['pcap']['packets'] for x in phases.values());memory=summary['memory_snapshot_total_mib']
page('01 / SYNTHÈSE','Synthèse et résultats',paragraph('CyberThreat est un environnement léger d’analyse des menaces réseau. Il met en relation un trafic contrôlé, les paquets capturés et les réponses d’une application HTTP synthétique. Les mêmes tests sont exécutés sur une version vulnérable puis sur une version durcie pour isoler l’effet des protections.')+table(['Indicateur','Résultat observé'],[['Scénarios','Reconnaissance TCP, rafale de connexion et injection SQL'],['Validation applicative',f"{summary['checks_passed']} contrôles réussis sur {summary['checks_total']}"],['Détection',f"{summary['alert_count']} alertes, trois familles dans chaque phase"],['Captures',f"{packet_total} paquets au total; deux PCAP"],['HTTP','11 requêtes extraites par phase'],['Budget RAM','512 MiB cumulés pour les deux services'],['Mesure RAM',f'{memory:g} MiB au snapshot de fin de scénario'],['Intégration','SDK MCP et connexion native OpenCode vérifiés']])+paragraph('Le scan reste observable après durcissement. La limitation des échecs produit HTTP 429 et la requête SQL paramétrée empêche la lecture des deux noms synthétiques. La détection d’une tentative et la confirmation de son effet sont évaluées séparément.')+callout('Périmètre de validation','Les preuves concernent une exécution locale reproductible. Aucun fichier soumis n’est exécuté; aucun appel à un modèle hébergé n’a été effectué. Les conteneurs partagent le noyau WSL2.')+paragraph(f'<span class="small">Référence : <code>{esc(RUN.name)}</code>. Les mesures de mémoire décrivent un instant après les tests, pas un benchmark au repos.</span>'))
page('02 / PÉRIMÈTRE','Objectifs et critères de réussite',table(['Objectif','Mise en œuvre','Critère'],[['Isoler le trafic','Réseau Docker interne et filtrage du bridge','Deux services; aucun port publié'],['Identifier les services','Nmap et Netcat','Port HTTP découvert et réponse conservée'],['Observer les comportements','dumpcap, TShark et événements JSONL','Captures non vides et trames identifiables'],['Reproduire les scénarios','Données fictives, cibles et arguments fixes','Comportements attendus vérifiés'],['Mesurer les protections','Comparaison vulnérable / durcie','Contrôles normaux conservés'],['Conserver les preuves','Artefacts structurés et SHA-256','Fichiers consultables et empreintes vérifiables']])+ '<h2>Choix d’architecture</h2>'+paragraph('Docker réduit le coût mémoire et permet un démarrage rapide. Ce choix ne remplit pas littéralement une exigence de deux machines virtuelles : les services utilisent le même noyau WSL2. La variante VM n’est pas implémentée ni testée dans cette livraison.')+'<h2>Frontière du projet</h2>'+paragraph('Les scénarios sont fixés sur une cible locale, sans shell distant, déni de service ni données personnelles. L’analyse de fichiers est statique. L’interface de bascule <code>/control</code> est un mécanisme de test accessible dans le réseau du projet, à retirer d’un service réel.')+callout('Distinction essentielle','Une alerte de reconnaissance peut provenir d’un inventaire autorisé. Une rafale d’échecs ne prouve pas un accès réussi. Une signature SQL ne prouve pas l’effet de la requête.'))
page('03 / ARCHITECTURE','Topologie et circulation des données',diagram('architecture','Figure 1. Architecture du projet et frontière réseau. Schéma explicatif de la configuration testée.')+table(['Composant','Fonction','Contrainte'],[['Station','Génération TCP/HTTP, capture et extraction','384 MiB / 0,75 CPU / 128 PID'],['Cible','HTTP Python et SQLite en mémoire','128 MiB / 0,50 CPU / 64 PID'],['MCP hôte','Commandes fixes et consultation des artefacts','Pas de socket Docker dans les services']])+paragraph('La station capture son propre trafic vers la cible. Elle n’est pas présentée comme un capteur passif de tout le bridge. Le client IA reste à l’extérieur des deux conteneurs et utilise le serveur local de confiance.')+paragraph('Le réseau est déclaré <code>internal: true</code>. Aucun port de service n’est publié sur l’hôte. Le guard INPUT bloque les nouvelles connexions venant du bridge et conserve les réponses aux connexions initiées depuis l’hôte.'))
page('04 / ISOLATION','Permissions et acteurs de confiance',diagram('trust-boundaries','Figure 2. Répartition des permissions et contrôles par acteur.')+table(['Acteur','Identité','Capacités / accès'],[['Cible','UID 1000','Aucune capacité effective'],['Capture station','UID 0','NET_RAW seulement; masque 0x2000'],['Worker statique','UID/GID 65534','Capacités nulles; preuves non modifiables'],['Hôte / moteur / MCP','De confiance','Pouvoir d’orchestration du projet']])+paragraph('Racines en lecture seule, seccomp et <code>no-new-privileges</code> sont actifs. Les montages sont limités aux preuves et aux échantillons, ces derniers en lecture seule. Aucun périphérique hôte ni espace PID/IPC hôte n’est partagé.')+callout('Limite du modèle','Les restrictions sont testées pour les acteurs du projet; elles ne démontrent pas l’impossibilité d’une faille du noyau, d’un parseur ou d’une modification par l’administrateur.'))
page('05 / OUTILS','Chaîne d’outils et versions observées',diagram('toolchain','Figure 3. Carte des outils, de leur rôle et de leurs artefacts. Cette illustration ne simule aucune interface.')+table(['Outil','Version ou identité enregistrée'],[[k,versions[k]] for k in ['nmap','tshark','tcpdump','yara','file','netcat','opencode']], 'dense')+paragraph('Les images d’interfaces et de sorties présentées dans les pages suivantes proviennent de captures GUI ou d’artefacts enregistrés. Les vues textuelles sont explicitement identifiées comme telles. Burp ne participe pas aux scénarios automatisés validés.'))
page('06 / MÉTHODE','Collecte, extraction et corrélation',diagram('pipeline','Figure 4. Chaîne de traitement implémentée, du trafic à la restitution.')+table(['Étape','Artefact','Interprétation'],[['Baseline','results.json','Fonctionnement normal de référence'],['Capture','vulnerable.pcap / hardened.pcap','Trafic observé dans chaque phase'],['Extraction','*-syn.tsv / *-http.tsv','Ports, URI, temps et trames'],['Application','app.jsonl','Échecs et décisions applicatives'],['Corrélation','alerts.json / results.json','Tentative et effet distingués'],['Synthèse','evidence-summary.json','Métadonnées calculées et chronologie']],'dense')+paragraph('La capture utilise dumpcap sans mode promiscuous. tcpdump lit ensuite les PCAP sous UID 1000. Cette séparation évite d’accorder CHOWN, SETUID ou SETGID à la station pour les mécanismes de changement d’utilisateur de tcpdump.'))
page('07 / RECONNAISSANCE','Inventaire TCP et vérification HTTP',figure(ASSETS/'nmap-output.png','Figure 5. Vue de la sortie Nmap réellement enregistrée dans vulnerable-nmap.txt.','output')+figure(ASSETS/'netcat-output.png','Figure 6. Vue de la réponse HTTP conservée par Netcat.','short-output')+paragraph('Le scan TCP connect vise les ports 1 à 100 et 8080, à un débit maximal configuré de 30 essais par seconde et avec une seule nouvelle tentative. Il découvre un port ouvert, 8080, sur une adresse locale fixe.')+paragraph('L’étiquette Nmap <code>http-proxy</code> est le nom de service associé au port dans sa base. En l’absence de <code>-sV</code>, elle ne prouve pas qu’un proxy est présent. La réponse GET <code>/health</code> confirme directement le service HTTP Python.'))
page('08 / CAPTURE','Inspection des connexions dans Wireshark',figure(RUN/'wireshark-vulnerable.png','Figure 7. Capture GUI réelle de Wireshark sur le PCAP vulnérable, filtrée sur les SYN initiaux.','wireshark')+table(['Mesure','Avant protection','Après protection'],[['Paquets',phases['vulnerable']['pcap']['packets'],phases['hardened']['pcap']['packets']],['Taille PCAP',str(phases['vulnerable']['pcap']['file_bytes'])+' octets',str(phases['hardened']['pcap']['file_bytes'])+' octets'],['Durée observée',str(phases['vulnerable']['pcap']['duration_seconds'])+' s',str(phases['hardened']['pcap']['duration_seconds'])+' s']])+paragraph('Filtre : <code>tcp.flags.syn == 1 &amp;&amp; tcp.flags.ack == 0</code>. Les métadonnées PCAP sont calculées à partir des en-têtes des paquets. Les tests rejettent les captures tronquées et comparent les empreintes aux fichiers effectivement livrés.'))
page('09 / HTTP','Requêtes, temps relatifs et trames',figure(ASSETS/'tshark-output.png','Figure 8. Vue des champs HTTP réellement extraits par TShark. Les URI sont des données non fiables.','output')+table(['Étape HTTP','Nombre par phase','Rôle'],[['GET / et lookup légitime','2','Contrôles applicatifs'],['GET /health','1','Vérification Netcat'],['POST /login','7','Six échecs puis contrôle correct'],['GET /users avec tautologie','1','Tentative SQL observée']])+paragraph('Le port TCP 8080 est explicitement décodé comme HTTP par TShark. La chronologie est relative à la première requête HTTP extraite de chaque phase, pas au début du fichier PCAP. Les numéros de trame sont propres au fichier sélectionné.')+callout('Corrélation','L’URI permet d’identifier la tentative. Les réponses JSON et les événements applicatifs vérifient la conséquence. Ces sources complémentaires empêchent d’assimiler un simple motif à une compromission.'))
page('10 / AUTHENTIFICATION','Effet de la limitation des échecs',figure(ASSETS/'login-responses.png','Figure 9. Codes de réponse observés, calculés depuis results.json. L’essai 7 utilise le mot de passe correct.','plot')+table(['Comportement','Vulnérable','Durci'],[['Six essais incorrects','401, 401, 401, 401, 401, 401','401, 401, 401, 429, 429, 429'],['Essai correct après rafale','200; authenticated=true','429; rate_limited'],['Recherche normale','200; labuser','200; labuser']])+paragraph('La protection mémorise les échecs par adresse source sur 60 secondes et limite les demandes après trois échecs. La règle LOGIN_BURST s’appuie sur les événements de connexion en échec, ce qui explique six événements avant durcissement et trois après.')+paragraph('Une connexion légitime est également bloquée après la rafale. En présence de NAT, plusieurs comptes peuvent partager cette adresse. La limite montre un effet mesurable, mais ne remplace pas une stratégie d’authentification combinant compte, source, temporisation et MFA.'))
page('11 / VALIDATION HTTP','Réponses de limitation dans Wireshark',figure(RUN/'wireshark-hardened.png','Figure 10. Capture GUI réelle de la phase durcie avec le filtre http.response.code == 429.','wireshark')+paragraph('Les réponses 429 confirment la décision de limitation au niveau réseau. Trois concernent les derniers mots de passe incorrects; une autre concerne le contrôle avec un mot de passe correct. La comparaison explique la perte temporaire de disponibilité, sans la masquer.')+table(['Source','Ce qu’elle démontre'],[['PCAP','Les réponses HTTP réellement transmises'],['results.json','L’ordre des demandes et les corps reçus'],['app.jsonl','La décision applicative et la phase associée']])+paragraph('Le trafic est volontairement HTTP en clair et contient exclusivement des identifiants fictifs. Un service réel doit utiliser TLS. Ce changement réduit la visibilité du contenu réseau et renforce l’importance des journaux applicatifs.'))
page('12 / SQL','Injection et requête paramétrée',diagram('sql-mitigation','Figure 11. Effet de la concaténation et de la liaison de paramètres, confirmé par les réponses.')+'<div class="columns"><div><h2>Avant protection</h2>'+pre(json.dumps(results['vulnerable']['sql_injection'][1],indent=2))+'</div><div><h2>Après protection</h2>'+pre(json.dumps(results['hardened']['sql_injection'][1],indent=2))+'</div></div>'+paragraph('Le paramètre reçoit une tautologie de type <code>\' OR \'1\'=\'1</code>. La version vulnérable interpole l’entrée dans la requête; la version durcie utilise une valeur paramétrée. La recherche légitime reste fonctionnelle.')+paragraph('La règle SQLI_PATTERN est volontairement spécifique à ce motif décodé. Elle peut manquer d’autres variantes. L’effet de la protection est établi par le résultat applicatif, pas par l’absence d’alerte.'))
alert_rows=[[a['mode'],a['rule'],a['evidence'],('trame '+a['frame']) if a.get('frame') else (str(a['distinct_ports'])+' ports') if a.get('distinct_ports') else str(a['count'])+' échecs'] for a in alerts]
page('13 / CORRÉLATION','Matrice des alertes et niveau de preuve',table(['Phase','Règle','Source','Observation'],alert_rows,'dense')+'<h2>Trois niveaux d’interprétation</h2>'+table(['Niveau','Exemple','Conclusion permise'],[['Observation','101 ports distincts visés','Reconnaissance détectée'],['Tentative','URI avec tautologie SQL','Motif d’injection observé'],['Effet vérifié','Deux noms retournés puis liste vide','Exposition reproduite puis empêchée']])+paragraph('Les trois familles persistent dans les deux phases. La requête renforcée empêche l’exposition et la limite bloque les connexions au-delà du seuil, mais les tentatives restent dans les captures. Le scan n’est pas bloqué par ces protections applicatives.')+callout('Faux positifs et couverture','Le trafic de référence ne mesure ni faux positifs à grande échelle ni taux de détection de variantes. Un inventaire autorisé peut déclencher SCAN_PORTS. La signature SQL exacte et les seuils fixes ne sont pas un IDS de production.'))
page('14 / INTERFACE','Investigation interactive et traçabilité',figure(RUN/'investigation-hardened.png','Figure 12. Capture réelle du tableau de bord : résultats durcis, codes HTTP et filtres de règles.','interface')+figure(RUN/'http-timeline.png','Figure 13. Chronologie liée aux trames du PCAP dans l’interface locale.','timeline')+paragraph('La nouvelle interface permet de basculer entre phases, filtrer les alertes par règle et texte, consulter la sortie Nmap enregistrée et exporter une synthèse JSON de la phase active. Les tests Chromium valident ces interactions et le contenu exporté.')+paragraph('Les chaînes et URI sont rendues avec textContent. Le contrôle HTML hostile reste du texte; aucune image injectée ni variable JavaScript de contrôle n’apparaît.'))
page('15 / MCP','Transport, orchestration et accès aux preuves',diagram('mcp-sequence','Figure 14. Séquence logique des appels MCP. Le schéma ne représente pas un appel LLM effectué.')+table(['Outil','Portée'],[['lab_status','État des services du projet'],['run_detection_demo','Scénario fixe et verrou de concurrence'],['list_evidence','Identifiants de runs'],['read_evidence','Artefacts autorisés, dont evidence-summary.json'],['static_triage','Analyse statique de fichier autorisé']],'dense')+paragraph('Le serveur s’exécute sur l’hôte de confiance et utilise des arguments fixes. Il ne propose ni commande shell générale, ni cible réseau arbitraire, ni exécution d’échantillon. L’agent OpenCode <code>threat-analyst</code> n’autorise que les outils <code>cyberthreat_*</code>.'))
page('16 / INTÉGRATION','Validation MCP et résistance des entrées',figure(ASSETS/'mcp-output.png','Figure 15. Vue du relevé de connexion native et des appels SDK réellement vérifiés.','output')+table(['Cas testé','Résultat'],[['SDK stdio : cinq outils','PASS'],['Scénario complet à travers MCP','PASS'],['État Docker et triage à travers MCP','PASS'],['Traversée, chemin absolu, artefact arbitraire','Rejetés'],['Métacaractères shell, lien symbolique, taille excessive','Rejetés'],['Protection du bridge absente','Triage refusé; succès après restauration']],'dense')+paragraph('La connexion native OpenCode est vérifiée séparément du client SDK. Aucune demande n’a été envoyée à un modèle hébergé. La qualité du raisonnement d’un LLM et sa résistance aux instructions présentes dans les échantillons ne sont pas démontrées par la connexion du transport.')+callout('Confiance du client','Les permissions de threat-analyst ne s’appliquent pas automatiquement aux autres agents. Le client peut transmettre les chaînes au fournisseur de modèle configuré; n’utiliser que le fixture public pour cette démonstration.'))
page('17 / TRIAGE','Inspection statique du fixture de contrôle',table(['Mesure','Valeur observée'],[['Fichier','harmless-training.txt'],['Taille',str(triage['bytes'])+' octets'],['Type',triage['file_description']],['Entropie',str(triage['entropy'])+' bits par octet'],['Exécuté','false'],['Verdict','Indéterminé; indicateurs statiques insuffisants'],['URI','https://telemetry.invalid/training']])+ '<h2>Règles YARA présentes</h2>'+table(['Règle','Ce qu’elle signale'],[['Lab_Training_Fixture','Marqueur du fichier inerte'],['Encoded_PowerShell_Indicator','Chaîne de commande encodée synthétique'],['Embedded_Instruction_Indicator','Instruction incorporée non fiable']])+paragraph('Le worker ne lance ni n’importe le fichier. Il borne les entrées à 10 MiB, calcule une empreinte et extrait des chaînes limitées, puis utilise file et YARA avec des délais. L’entropie décrit une distribution d’octets; elle n’est pas une classification de danger.')+'<h2>Empreinte du fixture</h2>'+pre(triage['sha256'])+callout('Contrôles adverses inertes','Une instruction de prompt injection et une chaîne HTML hostile sont incluses pour vérifier leur traitement comme données. Une correspondance YARA ne prouve pas la présence de malware réel.'))
checks=[('Sortie station',not runtime['station_external_connection'],'Référence hôte accessible'),('Sentinelle hôte',runtime['host_sentinel_denied'],'Refus depuis les deux services'),('Racine en lecture seule',all(v['rootfs_write_denied'] for v in runtime['container_probes'].values()),'Trois acteurs testés'),('Seccomp / no-new-privileges',all(v['seccomp_filter'] and v['no_new_privs'] for v in runtime['container_probes'].values()),'Actifs'),('Worker : preuves non modifiables',runtime['container_probes']['static_worker']['evidence_write_denied'],'UID/GID 65534'),('Socket Docker absent',all(v['docker_socket_absent'] for v in runtime['container_probes'].values()),'Pas de socket monté'),('Namespace mount',all(v['mount_namespace_denied'] for v in runtime['container_probes'].values()),'Création refusée'),('IPv6 désactivé',all(v['ipv6_disabled'] for v in runtime['container_probes'].values()),'Services du projet')]
page('18 / SÉCURITÉ','Contrôles runtime et limites résiduelles',table(['Contrôle','État','Périmètre'],[[n,'PASS' if ok else 'FAIL',context] for n,ok,context in checks],'dense')+'<h2>Base logicielle observée</h2>'+table(['Composant','Version'],[['Docker',audit['docker']],['runc',audit['runc']],['Noyau',audit['kernel']]])+paragraph('Les connexions externes sont testées avec une référence accessible depuis l’hôte. Le filtrage n’est pas une preuve d’isolation contre une faille du noyau. Les restrictions de capacités sont contrôlées sur les processus effectifs, distinctement des capacités éventuellement demandées puis refusées par dumpcap.')+paragraph('Le code MCP et le moteur ont le pouvoir d’orchestration du projet. Les parseurs file, YARA et les outils de capture peuvent eux-mêmes présenter des failles. Aucune garantie absolue d’absence d’évasion n’est revendiquée.')+callout('Portée de l’audit','Les namespaces hôte et périphériques sont absents; les limites PID/CPU et montages sont vérifiés. Ce n’est pas un audit exhaustif des CVE ni une validation de toutes les configurations Docker.'))
page('19 / RESSOURCES','Budget mémoire et coût opérationnel',figure(ASSETS/'memory-snapshot.png','Figure 16. Mémoire enregistrée après les scénarios, comparée aux limites configurées. Source : resources.txt.','plot')+table(['Service','Snapshot RAM','Plafond RAM','Plafond CPU'],[[m['service'],f"{m['usage_mib']:g} MiB",f"{m['limit_mib']:g} MiB",'0,75' if m['service']=='station' else '0,50'] for m in summary['memory_snapshot']])+paragraph(f'Le total observé dans ce snapshot est de <b>{memory:g} MiB</b>. Il dépend de l’activité au moment de la mesure et ne représente ni un pic maximal ni une moyenne au repos. Le plafond cumulé est de 512 MiB et 1,25 CPU pour les services.')+paragraph('Docker, son cache de construction, les interfaces graphiques, le Python MCP et WSL2 consomment des ressources supplémentaires. La première construction télécharge les paquets et peut être plus coûteuse que les exécutions suivantes.')+paragraph('Le noyau de la session ne fournit pas de limite de swap Docker. Le plafond RAM est effectif et testé. Les GUI sont ouvertes uniquement pour l’inspection et fermées après les captures.'))
page('20 / EXPLOITATION','Exécution et dossier d’artefacts',pre('git clone https://github.com/Wael-Rd/CyberThreat.git\ncd CyberThreat\n./scripts/lab.sh doctor\n./scripts/lab.sh build\n./scripts/lab.sh up\n./scripts/lab.sh run\n./scripts/lab.sh down')+paragraph('Cloner dans le système de fichiers Linux, avec les permissions Unix attendues. Les montages Windows peuvent empêcher la restriction d’écriture du worker. La configuration suppose UID 1000, accès Docker et sudo non interactif pour le filtrage.')+table(['Artefact','Utilité'],[['PCAP','Trafic des deux phases'],['Nmap XML/TXT, Netcat','Découverte et confirmation du service'],['TSV SYN/HTTP','Ports, URI, temps et trames'],['app.jsonl','Événements applicatifs'],['results.json / alerts.json','Effets vérifiés et tentatives détectées'],['evidence-summary.json','Métadonnées, chronologie et mesure mémoire'],['runtime-checks.json / sandbox-audit.json','Contrôles de la frontière et des permissions'],['SHA256SUMS','Vérification des fichiers livrés']],'dense')+paragraph('Le runbook du dépôt documente l’inspection et les tests. Le moteur dédié optionnel reste local, sans stockage Docker dans Git. Une seule copie active du projet et un seul scénario simultané sont recommandés.'))
page('21 / RECOMMANDATIONS','Priorités d’amélioration',table(['Priorité','Mesure','Justification'],[['P1','Maintenir les paramètres SQL','Empêcher la concaténation d’entrées'],['P1','TLS et gestion sûre des secrets','Éviter la visibilité des identifiants réels'],['P1','Retirer /control hors laboratoire','Empêcher une bascule de mode abusive'],['P1','Authentification multi-facteur','Réduire l’effet des mots de passe compromis'],['P2','Limites par compte et source','Réduire l’impact des adresses partagées'],['P2','Journalisation centralisée','Corréler décisions, temps et identités'],['P2','Tests sur trafic bénin et variantes','Mesurer faux positifs et couverture'],['P3','Détection temporelle plus riche','Remplacer les seuls seuils fixes'],['P3','VM jetables pour analyse dynamique','Créer une frontière distincte du poste']],'dense')+'<h2>Évolutions déjà intégrées</h2>'+paragraph('Le projet inclut désormais une synthèse structurée des PCAP, une chronologie liée aux trames, une recherche d’alertes, un export JSON par phase et des tests de rejet de captures malformées. Ces fonctionnalités utilisent les artefacts réels plutôt que des valeurs figées.')+callout('Critère de passage en production','Évaluer sur des jeux indépendants, documenter les faux positifs et assurer la surveillance des composants. Le laboratoire ne constitue pas une solution de supervision de production.'))
page('22 / INTÉGRITÉ','Traçabilité et limites de démonstration',paragraph('Les empreintes des captures relient le rapport aux fichiers PCAP. Les images Wireshark sont des captures GUI. Les vues Nmap, Netcat, TShark et MCP reproduisent des sorties enregistrées; les schémas sont explicatifs et les graphiques sont calculés depuis les données.')+table(['Fichier','SHA-256'],[[mode+'.pcap',phases[mode]['pcap']['sha256']] for mode in ['vulnerable','hardened']],'hash-table')+pre('cd evidence/'+RUN.name+'\nsha256sum -c SHA256SUMS')+paragraph('Le manifeste détecte une modification par comparaison avec une copie conservée séparément. Il n’est pas une signature face à un administrateur qui remplace à la fois le fichier et le manifeste. Les chemins propres au poste sont retirés du snapshot Compose publié.')+'<h2>Validation restante</h2>'+paragraph('L’analyse par un modèle hébergé, Burp GUI/Repeater et la variante deux VM ne font pas partie des tests démontrés. Les scores de faux positifs, le débit maximal et la résistance à toutes les variantes d’attaque n’ont pas été mesurés.')+callout('Conclusion','La solution démontre un workflow reproductible d’analyse des menaces : observer, corréler, vérifier l’effet et conserver les preuves. Sa valeur vient de la séparation explicite entre observations, interprétation et limites.'))
page('23 / RÉFÉRENCES','Documentation et vocabulaire',table(['Terme','Définition utilisée'],[['PCAP','Capture contenant des paquets et leurs horodatages'],['MCP','Protocole de liaison entre client et outils locaux'],['YARA','Règles de motifs statiques à interpréter'],['Triage','Inspection initiale, sans conclusion automatique'],['Guard du bridge','Filtrage dédié des nouvelles connexions vers l’hôte'],['Tentative / effet','Motif observé / conséquence confirmée']],'dense')+'<h2>Sources primaires</h2>'+'<ol class="references"><li><a href="https://docs.docker.com/reference/compose-file/networks/">Docker Compose, réseaux et réseau interne</a></li><li><a href="https://docs.docker.com/reference/compose-file/services/">Docker Compose, services et limites</a></li><li><a href="https://www.wireshark.org/docs/man-pages/tshark">Wireshark, manuel TShark</a></li><li><a href="https://www.wireshark.org/docs/man-pages/wireshark-filter">Wireshark, filtres d’affichage</a></li><li><a href="https://nmap.org/book/man.html">Nmap, guide de référence</a></li><li><a href="https://github.com/modelcontextprotocol/python-sdk">MCP, SDK Python officiel</a></li><li><a href="https://docs.opencode.ai/docs/mcp-servers/">OpenCode, serveurs MCP</a></li><li><a href="https://docs.opencode.ai/docs/permissions/">OpenCode, permissions</a></li><li><a href="https://yara.readthedocs.io/en/stable/">YARA, documentation</a></li></ol>'+paragraph('Les valeurs et les conclusions de ce rapport proviennent des artefacts du run de référence. Les documentations ci-dessus expliquent les fonctions des outils; elles ne remplacent pas les preuves d’exécution.'))
# Replace the contents page with compact, clickable chapter entries.
toc='<div class="toc">'+''.join(f'<a href="#page-{n}"><span>{esc(label.split(" / ")[0])}</span><b>{esc(title)}</b><i>{n:02}</i></a>' for n,label,title in sections)+'</div>'
pages[1]=f'<section class="page" id="page-2"><header><span>CYBERTHREAT / THREAT ANALYSIS</span><span>PLAN DU RAPPORT</span></header><h1>Sommaire</h1>{toc}<footer><span>Rapport illustré / méthodologie et preuves</span><span>02</span></footer></section>'
css='''@page{size:A4;margin:0}*{box-sizing:border-box}body{margin:0;font-family:"Liberation Sans",Arial,sans-serif;color:#2e3946;font-size:9.4pt;line-height:1.48;-webkit-print-color-adjust:exact;print-color-adjust:exact}.page{width:210mm;height:297mm;padding:15mm 18mm 19mm;position:relative;break-after:page;background:#fff}.page:last-child{break-after:auto}header{display:flex;justify-content:space-between;font-size:7pt;letter-spacing:.8px;color:#64758a;padding-bottom:4mm;border-bottom:1px solid #cbd5e0}h1{font-family:"Liberation Serif",Georgia,serif;color:#20354e;font-size:28pt;line-height:1.1;font-weight:700;letter-spacing:-.4px;margin:7mm 0 6mm}h2{font-size:12pt;color:#355779;margin:5mm 0 2mm}p{margin:2.5mm 0 4mm}a{color:#365d87}table{width:100%;border-collapse:collapse;font-size:8.7pt;margin:4mm 0;table-layout:fixed}th{text-align:left;background:#253d58;color:white;padding:2.8mm;font-weight:600}td{padding:2.5mm;border-bottom:1px solid #dce3ea;vertical-align:top;overflow-wrap:anywhere}tr:nth-child(even)td{background:#f5f7fa}.dense{font-size:8.2pt}.dense td{padding:2.2mm}.hash-table td:nth-child(2){font:7.3pt monospace;word-break:break-all}.hash-table th:first-child{width:30%}aside{background:#f0f4f8;border-left:2px solid #607f9f;padding:3mm 4mm;margin:4mm 0}aside b{font-size:9pt;color:#284561}aside p{margin:1.5mm 0 0;font-size:8.7pt}pre{white-space:pre-wrap;word-break:break-all;background:#f2f5f8;border:1px solid #d8e1eb;padding:3mm;font:8.3pt monospace;line-height:1.6;color:#28415e;margin:3mm 0}code{font:8.2pt monospace;color:#28415e;background:#f0f3f7;padding:1px 3px}.columns{display:grid;grid-template-columns:1fr 1fr;gap:5mm}figure{margin:3mm 0 5mm}figure img{display:block;width:100%;max-height:108mm;object-fit:contain;object-position:left center}figcaption{font-size:7.7pt;color:#617286;line-height:1.45;margin-top:2mm}.diagram img{max-height:94mm}.output img{max-height:88mm;border:1px solid #d1dce7}.short-output img{max-height:59mm;border:1px solid #d1dce7}.wireshark img{max-height:130mm;border:1px solid #d1dce7}.plot img{max-height:105mm}.interface img{max-height:106mm;border:1px solid #d1dce7}.timeline img{max-height:76mm;border:1px solid #d1dce7}footer{position:absolute;left:18mm;right:18mm;bottom:9mm;border-top:1px solid #cbd5e0;padding-top:3mm;display:flex;justify-content:space-between;font-size:6.5pt;color:#68798b;letter-spacing:.3px}.small{font-size:8pt;color:#64758a}.toc a{display:flex;align-items:center;gap:4mm;text-decoration:none;color:#314760;padding:2.25mm 0;border-bottom:1px solid #e4e9ef;font-size:9pt}.toc span{font-size:8pt;color:#8493a5;width:7mm}.toc b{font-weight:400;flex:1}.toc i{font-style:normal;font-size:8pt;color:#677a8f}.cover{padding:19mm 20mm}.cover header{font-size:8pt}.cover-category{margin-top:14mm;font-size:8pt;letter-spacing:1.5px;color:#63768d}.cover h1{font-size:36pt;line-height:1.13;margin:8mm 0 5mm}.cover h2{font-size:17pt;font-weight:400;color:#59718b;margin:0}.cover-sub{font-size:10.5pt;color:#5c6f84;line-height:1.7;margin-top:7mm}.cover-diagram{margin:8mm 0 6mm}.cover-diagram img{max-height:79mm}.cover-diagram figcaption{font-size:7pt}.cover-bottom{display:grid;grid-template-columns:1fr 1fr;gap:10mm;border-top:1px solid #cbd5e0;padding-top:5mm;margin-top:5mm}.cover-bottom p{font-size:12pt;color:#304c69;line-height:1.7}.label{font-size:7pt;letter-spacing:1px;color:#76879b}.references{font-size:9pt;padding-left:5mm;line-height:1.75}.references li{margin:2mm 0}'''
report=OUT/'CyberThreat-Technical-Report.html'
report.write_text('<!doctype html><html lang="fr"><head><meta charset="utf-8"><title>CyberThreat | Threat Analysis</title><style>'+css+'</style></head><body>'+''.join(pages).replace(chr(8212),':')+'</body></html>')
pdf=report.with_suffix('.pdf')
with sync_playwright() as p:
    browser=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox','--disable-gpu'])
    tab=browser.new_page(viewport={'width':1100,'height':1200});tab.goto(report.as_uri(),wait_until='load');tab.emulate_media(media='print')
    issues=tab.locator('.page').evaluate_all('(pages)=>pages.map((p,i)=>({page:i+1,last:Math.max(...[...p.children].filter(e=>e.tagName!=="FOOTER").map(e=>e.getBoundingClientRect().bottom)),footer:p.querySelector("footer").getBoundingClientRect().top})).filter(x=>x.last>x.footer-8)')
    if issues:raise RuntimeError('Report content overlaps footer: '+json.dumps(issues))
    tab.pdf(path=str(pdf),format='A4',print_background=True,prefer_css_page_size=True,tagged=True,outline=True)
    for number in [1,5,9,14,16]:
        tab.locator(f'#page-{number}').screenshot(path=str(ASSETS/f'report-preview-{number:02}.png'))
    browser.close()
(OUT/'SHA256SUMS').write_text(''.join(hashlib.sha256(f.read_bytes()).hexdigest()+'  '+f.name+'\n' for f in [report,pdf]))
validation={'pages':len(pages),'figures':16,'source_run':RUN.name,'footer_overlaps':[],'embedded_images':True,'tagged_pdf':True,'long_dash_removed':True}
(OUT/'report-validation.json').write_text(json.dumps(validation,indent=2)+'\n')
export=os.environ.get('CYBERTHREAT_EXPORT_DIR')
if export:
    directory=Path(export);directory.mkdir(parents=True,exist_ok=True)
    for f in [report,pdf]:shutil.copy2(f,directory/f.name)
print(f'PASS illustrated report: {len(pages)} pages, 16 figures, no footer overlap; {pdf.stat().st_size} bytes')
